#include "syr2k.hpp"

using num_t = DATA_TYPE;

namespace {

// basic dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

// layout tuning (can be changed independently of the algorithm)
struct tuning {
	// C is N x N, indexed by (i, j)
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec); // physical layout: j (outer) x i (inner)

	// A is N x M, indexed by (i, k)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec); // physical layout: k (outer) x i (inner)

	// B is N x M, indexed by (i, k)
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ i_vec); // physical layout: k (outer) x i (inner)

	// Kernel tuning parameters (can be adjusted for a given machine)
	static constexpr bool use_strict_triangular_traversal = true;
} tuning;

// initialization function
// C: i x j  (N x N)
// A: i x k  (N x M)
// B: i x k  (N x M)
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// Initialize A: A[i][k] = ( (i * k + 1) % n ) / n
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		auto n_len  = A | get_length<'i'>(); // corresponds to original 'n'
		A[state] = (num_t)((i * k + 1) % n_len) / n_len;
	});

	// Initialize B: B[i][k] = ( (i * k + 2) % m ) / m
	traverser(B).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		auto m_len  = B | get_length<'k'>(); // corresponds to original 'm'
		B[state] = (num_t)((i * k + 2) % m_len) / m_len;
	});

	// Initialize C: C[i][j] = ( (i * j + 3) % n ) / m
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		auto n_len  = C | get_length<'i'>(); // N
		auto m_len  = B | get_length<'k'>(); // M
		C[state] = (num_t)((i * j + 3) % n_len) / m_len;
	});
}

// computation kernel
// BLAS-like SYR2K:
//
// C := alpha * A * B^T + alpha * B * A^T + beta * C
//
// with:
//   A: N x M
//   B: N x M
//   C: N x N (only lower-triangular part (i,j) with j <= i is updated)
[[gnu::flatten, gnu::noinline]]
void kernel_syr2k(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j   (layout: j outer, i inner  -> contiguous in i for fixed j)
	// A,B: i x k (layout: k outer, i inner -> contiguous in i for fixed k)
	//
	// We choose the logical loop order:
	//   for j = 0..N-1
	//     for i = j..N-1
	//       C[i][j] *= beta;
	//
	//   for j = 0..N-1
	//     for k = 0..M-1
	//       Ajk = A[j][k], Bjk = B[j][k]   // reused across i
	//       for i = j..N-1
	//         C[i][j] += alpha * (Ajk * B[i][k] + Bjk * A[i][k]);
	//
	// This ordering has two important properties:
	//   - For fixed (j,k), the inner loop over i walks the *inner* dimension of
	//     C, A and B, giving cache- and SIMD-friendly, contiguous accesses.
	//   - The triangular condition j <= i is enforced by restricting the
	//     traverser over 'i' using noarr::shift, so we do not iterate the upper
	//     triangle at all (no branch in the hot loops).

#pragma scop

	// -------------------------------------------------------------------------
	// 1) Scale the lower-triangular part of C by beta
	//    C[i][j] = beta * C[i][j]  for all 0 <= j <= i < N
	// -------------------------------------------------------------------------
	if constexpr (tuning::use_strict_triangular_traversal) {
		// Iterate over columns j; for each j, only visit rows i >= j.
		traverser(C).template for_dims<'j'>([&](auto trav_j) {
			auto state_j = trav_j.state();
			auto j_idx   = get_index<'j'>(state_j);

			// Limit this traverser to i in [j_idx, N) using shift<'i'>(j_idx).
			// After order(shift), the states seen by for_each already contain
			// the original (shifted) i indices (i >= j_idx).
			auto trav_lower = trav_j.order(shift<'i'>(j_idx));

			trav_lower.for_each([&](auto state) {
				// state has 'i' and 'j' with i >= j
				C[state] *= beta;
			});
		});
	} else {
		// Fallback: iterate full matrix and guard with j <= i (kept for
		// completeness / experimentation).
		traverser(C).template for_dims<'j'>([&](auto trav_j) {
			trav_j.for_each([&](auto state) {
				auto [i_idx, j_idx] = get_indices<'i', 'j'>(state);
				if (j_idx <= i_idx)
					C[state] *= beta;
			});
		});
	}

	// -------------------------------------------------------------------------
	// 2) Rank-2k update on the lower triangle:
	//
	//    C[i][j] += alpha * A[j][k] * B[i][k]
	//               + alpha * B[j][k] * A[i][k],
	//
	//    for all 0 <= j <= i < N and 0 <= k < M.
	//
	//    Loop order chosen for locality:
	//      j (column of C)  -> k (column of A,B) -> i (row, inner dim)
	// -------------------------------------------------------------------------
	traverser(C, A, B).template for_dims<'j'>([&](auto trav_j) {
		auto state_j = trav_j.state();
		auto j_idx   = get_index<'j'>(state_j);

		// For each fixed j, iterate over all k. The traverser now has 'k' and
		// 'i' remaining, but we immediately fix 'k' and keep 'i' for the inner
		// loop.
		trav_j.template for_dims<'k'>([&](auto trav_jk) {
			auto state_jk = trav_jk.state();
			auto k_idx    = get_index<'k'>(state_jk);

			// Preload A[j][k] and B[j][k]; they are reused across all i>=j.
			auto jk_state = idx<'i', 'k'>(j_idx, k_idx);
			num_t Ajk     = A[jk_state];
			num_t Bjk     = B[jk_state];

			// Fuse the multiplication by alpha with Ajk/Bjk so that the inner
			// loop only pays two multiplies per element update.
			num_t alpha_Ajk = alpha * Ajk;
			num_t alpha_Bjk = alpha * Bjk;

			// Now traverse rows i >= j. We again use shift<'i'>(j_idx) on the
			// traverser so that we only visit the lower-triangular part for
			// this column j.
			auto trav_jk_lower = trav_jk.order(shift<'i'>(j_idx));

			trav_jk_lower.for_each([&](auto state) {
				// state has indices (i, j, k) with i >= j.
				auto i_idx = get_index<'i'>(state);

				// A[i][k], B[i][k]  (contiguous in i for fixed k)
				auto ik_state = idx<'i', 'k'>(i_idx, k_idx);
				num_t Aik     = A[ik_state];
				num_t Bik     = B[ik_state];

				// C[i][j]  (contiguous in i for fixed j)
				C[state] += alpha_Ajk * Bik + alpha_Bjk * Aik;
			});
		});
	});

#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// scalar parameters
	num_t alpha;
	num_t beta;

	// set lengths for all relevant dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(m);

	// allocate bags for C, A, B with selected layouts and lengths
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	// start timer
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_syr2k(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	// stop timer
	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (only when some argument is given, mimicking PolyBench's DCE guard)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' to make the output row-major in (i, j)
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
