// include common definitions (DATA_TYPE, N, M, DEFINE_PROTO_STRUCT, ...)
#include "defines.hpp"

// include benchmark-specific definitions (N, M, DATA_TYPE, etc.)
#include "syr2k.hpp"

using num_t = DATA_TYPE;

namespace {

// basic dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

// layout tuning (can be changed independently of the algorithm)
struct tuning {
	// C is N x N, indexed by (i, j)
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec); // logical dims: i (row), j (col); j is the innermost/contiguous dim

	// A is N x M, indexed by (i, k)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec); // logical dims: i (row), k (col); k is the innermost/contiguous dim

	// B is N x M, indexed by (i, k)
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ i_vec); // same as A
} tuning;

// initialization function
// C: i x j  (N x N)
// A: i x k  (N x M)
// B: i x k  (N x M)
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// Query lengths once; avoid recomputing them inside the traversals.
	const auto n_len = A | get_length<'i'>(); // corresponds to original 'n'
	const auto m_len = A | get_length<'k'>(); // corresponds to original 'm'

	// Initialize A: A[i][k] = ( (i * k + 1) % n ) / n
	traverser(A).for_each([&](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % n_len) / (num_t)n_len;
	});

	// Initialize B: B[i][k] = ( (i * k + 2) % m ) / m
	traverser(B).for_each([&](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		B[state] = (num_t)((i * k + 2) % m_len) / (num_t)m_len;
	});

	// Initialize C: C[i][j] = ( (i * j + 3) % n ) / m
	// Note: use the same n_len and m_len as above.
	traverser(C).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 3) % n_len) / (num_t)m_len;
	});
}

// computation kernel
// BLAS-like SYR2K:
//
//   C := alpha * A * B^T + alpha * B * A^T + beta * C
//
// with:
//   A: N x M
//   B: N x M
//   C: N x N (only lower-triangular part (i,j) with j <= i is updated)
//
// Optimized version notes
// ------------------------
// 1. We fuse the original two loop nests:
//
//      C[i][j] *= beta;
//      C[i][j] += sum_k alpha*(A[j][k]*B[i][k] + B[j][k]*A[i][k]);
//
//    into a single traversal that computes
//
//      C[i][j] = beta * C[i][j] +
//                sum_k alpha*(A[j][k]*B[i][k] + B[j][k]*A[i][k])
//
//    for j <= i and leaves C[i][j] unchanged for j > i.
//    This halves the number of passes over C, improving memory locality.
//
// 2. Loop ordering is i -> j -> k:
//      - 'i' is the outer traversal dimension;
//      - 'j' is the middle dimension (we apply the j <= i triangular guard);
//      - 'k' is the innermost, giving contiguous access in the 'k' dimension of
//        A and B (layout k_vec ^ i_vec => k is inner).
//
//    For a fixed (i,j), the inner-most loop walks k, and we read full rows
//    A[i][*], B[i][*], A[j][*], B[j][*] contiguously in memory.
//
// 3. All loops are expressed via Noarr traversers (for_dims / for_each) as
//    required. States are used for element accesses and minor index rewrites.
//
[[gnu::flatten, gnu::noinline]]
void kernel_syr2k(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: dims (i, j)
	// A: dims (i, k)
	// B: dims (i, k)

#pragma scop
	// Outer loop over i (rows of C).
	// We start from a joint traverser over C, A, B so that shared dimensions
	// ('i', 'k') are iterated only once.
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed; remaining dimensions are 'j' and 'k'.

		// Middle loop over j (columns of C).
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			// trav_ij has both 'i' and 'j' fixed; remaining dimension is 'k'.

			auto state_ij = trav_ij.state();
			const auto i_idx = get_index<'i'>(state_ij);
			const auto j_idx = get_index<'j'>(state_ij);

			// We only update the lower-triangular part: j <= i.
			if (j_idx > i_idx)
				return; // upper-triangular element, leave C[i][j] unchanged

			// Scale C[i][j] by beta once and keep it in a register.
			num_t cij = C[state_ij] * beta;

			// Inner loop over k (shared dimension of A and B).
			// For each k we use:
			//   - A[i][k], B[i][k] via the current state (i,j,k) where A/B
			//     ignore 'j';
			//   - A[j][k], B[j][k] via a modified state where we replace
			//     the 'i' component by j_idx.
			trav_ij.for_each([&](auto state_ijk) {
				// state_ijk has indices (i, j, k)
				// A and B only care about (i, k).

				// A[i][k] and B[i][k]
				const num_t A_ik = A[state_ijk];
				const num_t B_ik = B[state_ijk];

				// Build a state with (i = j_idx, k = current k):
				// A[j][k], B[j][k]
				auto state_jk = state_ijk.template with<index_in<'i'>>(j_idx);
