				//   alpha * (A[j][k] * B[i][k] + B[j][k] * A[i][k])
				const num_t term =
					A_jk * B_ik +
					B_jk * A_ik;

				cij += alpha * term;
			});

			// Write the updated value back to C[i][j].
			C[state_ij] = cij;
		});
	});
#pragma endscop
}

