	//
	//   for (i = 0; i < N; i++)
	//     for (k = 0; k < M; k++) {
	//       for (j = 0; j <= i; j++) {
	//         C[i][j] += alpha * ( A[j][k] * B[i][k]
	//                            + B[j][k] * A[i][k] );
	//       }
